INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('topic:KURS-049','topic','','Naprawa przycisku zasilania','','description: Naprawa niedziałającego lub zacinającego się włącznika laptopa. symptoms: • Laptop nie reaguje na przycisk power • Przycisk zapada się / trzeba mocno naciskać • Włącza się dopiero po kilku próbach diagnosis: • Sprawdź, czy laptop startuje po zwarciu pinów włącznika na płycie. • Oceń stan taśmy przycisku (często wspólna z klawiaturą). • Zweryfikuj mikroprzełącznik (tact switch). repair: • Podłącz ponownie taśmę przycisku. • Wymień mikroprzełącznik / moduł włącznika. • Przelutuj oderwane styki włącznika. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-050','topic','','Diagnoza: laptop się nie włącza','','description: Metodyczna diagnoza martwego laptopa — od zasilania po płytę główną. symptoms: • Brak reakcji na przycisk power • Diody nie świecą / laptop martwy • Wentylator ruszy i zaraz gaśnie diagnosis: • Sprawdź ładowarkę (dioda, napięcie miernikiem) i gniazdo DC-IN. • Odłącz baterię, spróbuj z samej ładowarki. • Zmierz pobór prądu na zasilaniu (zwarcie = stały wysoki pobór). • Odłącz RAM/dysk/WiFi — próba startu na minimum. repair: • Wymień ładowarkę / gniazdo ładowania, jeśli brak zasilania. • Zresetuj EC (power drain: przytrzymaj power 30 s bez baterii). • Znajdź i wymień zwarty element / uszkodzoną sekcję zasilania (serwis). • Wymień/odśwież BIOS przy braku POST. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-051','topic','','Diagnoza: brak obrazu / czarny ekran','','description: Ustalenie, czy czarny ekran to wina matrycy, podświetlenia, GPU czy płyty. symptoms: • Laptop działa (diody/wiatrak), ale ekran czarny • Obraz pojawia się dopiero na HDMI • Ekran ledwo widoczny pod latarką diagnosis: • Podłącz monitor zewnętrzny — obraz OK = wina matrycy/taśmy/podświetlenia. • Poświeć latarką na ekran — widać obraz = wina podświetlenia. • Brak obrazu też na HDMI = wina GPU/płyty/RAM. • Przełóż/wyczyść RAM. repair: • Wymień taśmę eDP / matrycę / sekcję podświetlenia. • Reflow/reball lub wymiana GPU (serwis) przy braku obrazu na HDMI. • Wymień RAM, zresetuj BIOS. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-052','topic','','Diagnoza: samoczynne wyłączanie','','description: Laptop wyłącza się lub restartuje sam — najczęściej przegrzewanie lub zasilanie. symptoms: • Wyłączenia pod obciążeniem (gry/render) • Nagłe restarty bez BSOD • Wyłącza się po kilku minutach diagnosis: • Monitoruj temperatury (HWiNFO) — >95°C = przegrzewanie. • Sprawdź baterię/ładowarkę (nagłe zaniki napięcia). • Sprawdź logi zdarzeń Windows (Kernel-Power 41). repair: • Wymień pastę, wyczyść chłodzenie. • Wymień wadliwą baterię/ładowarkę. • Sprawdź sekcję zasilania (VRM) i kondensatory. • Testuj RAM i sterowniki przy błędach systemowych. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-053','topic','','Naprawa: artefakty / pasy na ekranie','','description: Kolorowe piksele, pasy i zniekształcenia — zwykle GPU, VRAM lub matryca. symptoms: • Kolorowe kwadraty / kropki na ekranie • Poziome/pionowe pasy • Artefakty w grach i w BIOS diagnosis: • Artefakty widoczne też w BIOS/na HDMI = wina GPU/VRAM. • Artefakty tylko na matrycy = matryca/taśma. • Test obciążeniowy GPU (FurMark) i temperatury VRAM. repair: • Przeinstaluj sterowniki (DDU) i wyklucz software. • Wymień pady termiczne VRAM, popraw chłodzenie. • Reflow/reball lub wymiana GPU (serwis BGA). • Wymień matrycę/taśmę przy winie ekranu. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-054','topic','','Aktualizacja i naprawa sterowników','','description: Poprawna instalacja sterowników — stabilność, wydajność i koniec problemów sprzętowych. symptoms: • Wykrzykniki w Menedżerze urządzeń • Brak dźwięku / WiFi / obrazu po instalacji Windows • Błędy sterownika (code 43/10) diagnosis: • Sprawdź Menedżer urządzeń pod kątem nieznanych urządzeń. • Ustal model płyty/laptopa i pobierz sterowniki ze strony producenta. • Zweryfikuj wersje (chipset, GPU, sieć, audio). repair: • Instaluj sterowniki w kolejności: chipset → GPU → sieć → audio → reszta. • GPU: czysta instalacja (DDU + najnowszy sterownik). • Cofnij problematyczny sterownik (Roll Back). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-055','topic','','Optymalizacja i przyspieszenie Windows','','description: Bezpieczne przyspieszenie systemu bez ryzykownych „cudownych” programów. symptoms: • Wolny start i uruchamianie programów • Zamulony system, wysokie użycie dysku • Dużo programów w autostarcie diagnosis: • Sprawdź autostart (Menedżer zadań → Uruchamianie). • Zweryfikuj wolne miejsce na dysku systemowym. • Sprawdź, czy system jest na SSD. repair: • Wyłącz zbędne aplikacje w autostarcie. • Odinstaluj bloatware, wyczyść pliki tymczasowe. • Przenieś system na SSD, włącz plan zasilania Wysoka wydajność. • Sprawdź złośliwe oprogramowanie. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-056','topic','','Naprawa rozruchu Windows (boot)','','description: Naprawa systemu, który nie startuje — bootloader, BCD, pliki systemowe. symptoms: • Komunikat No bootable device / 0xc000000e • Pętla automatycznej naprawy • Windows nie ładuje pulpitu diagnosis: • Ustal, czy dysk jest wykrywany w BIOS. • Sprawdź tryb boot (UEFI vs Legacy) i kolejność. • Uruchom środowisko naprawcze (WinRE) z pendrive. repair: • bootrec /fixmbr, /fixboot, /rebuildbcd. • sfc /scannow i DISM /RestoreHealth. • Odbuduj partycję EFI (bcdboot). • Ostatecznie: naprawcza reinstalacja z zachowaniem plików. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-057','topic','','BitLocker — odblokowanie szyfrowania','','description: Odblokowanie i zarządzanie zaszyfrowanym dyskiem BitLocker (klucz odzyskiwania). symptoms: • Ekran BitLocker prosi o klucz odzyskiwania • Brak dostępu do dysku po wymianie płyty/BIOS • Zablokowany dysk po awarii diagnosis: • Znajdź klucz odzyskiwania na koncie Microsoft (account.microsoft.com/devices/recoverykey). • Ustal przyczynę (zmiana TPM/BIOS/kolejności boot). • Sprawdź, czy dane są niezbędne (bez klucza = brak odzysku). repair: • Wpisz 48-cyfrowy klucz odzyskiwania. • Zawieś BitLocker przed aktualizacją BIOS (manage-bde -protectors -disable). • Po odblokowaniu: kopia danych, ewentualnie wyłącz szyfrowanie. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-058','topic','','Naprawa Windows Update','','description: Rozwiązywanie błędów aktualizacji systemu (zawieszone, kody błędów). symptoms: • Aktualizacje utknęły na X% • Kody błędów (0x800..., 0x8024...) • Pętla instalowania/cofania aktualizacji diagnosis: • Uruchom narzędzie rozwiązywania problemów Windows Update. • Sprawdź wolne miejsce i połączenie z siecią. • Zweryfikuj datę/godzinę systemu. repair: • Zatrzymaj usługi (wuauserv, bits), wyczyść folder SoftwareDistribution. • sfc /scannow i DISM /RestoreHealth. • Zainstaluj aktualizację ręcznie (Katalog Microsoft Update). • Reset składników Windows Update. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-059','topic','','Kalibracja i kondycja baterii','','description: Poprawa dokładności wskazań i ocena zużycia baterii laptopa. symptoms: • Bateria szybko spada z 100% / nagły skok do 0% • Krótki czas pracy • Nieprawidłowe wskazania procentów diagnosis: • Wygeneruj raport baterii: powercfg /batteryreport. • Porównaj pojemność projektową z pełną (zużycie). • Sprawdź cykle ładowania. repair: • Skalibruj: pełne naładowanie → pełne rozładowanie → pełne ładowanie. • Ustaw limit ładowania (np. 80%) w oprogramowaniu producenta. • Wymień baterię przy zużyciu >30–40%. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-060','topic','','Naprawa USB-C / Thunderbolt','','description: Diagnoza i naprawa portów USB-C (dane, zasilanie PD, obraz DP-Alt, Thunderbolt). symptoms: • Nie ładuje przez USB-C • Brak obrazu/danych z USB-C • Port luźny / uszkodzony mechanicznie diagnosis: • Test innym kablem/zasilaczem PD i innym urządzeniem. • Sprawdź sterowniki i firmware Thunderbolt. • Obejrzyj port pod kątem wygiętych pinów/zwarcia. repair: • Wymień gniazdo USB-C (lutowanie SMD, gęste piny — serwis). • Napraw kontroler PD / retimer na płycie. • Zaktualizuj firmware/sterowniki Thunderbolt. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-061','topic','','Naprawa wyjścia HDMI / DisplayPort','','description: Naprawa braku obrazu na monitorze zewnętrznym przez HDMI/DP. symptoms: • Monitor zewnętrzny nie wykrywany • Migotanie / brak sygnału HDMI • Obraz tylko w niskiej rozdzielczości diagnosis: • Test innym kablem i monitorem. • Sprawdź wybór wyświetlacza (Win+P) i sterowniki GPU. • Obejrzyj gniazdo HDMI/DP pod kątem uszkodzeń. repair: • Zaktualizuj sterowniki GPU/chipset. • Wymień/przelutuj gniazdo HDMI/DP. • Sprawdź ścieżki i elementy toru sygnału (serwis). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-062','topic','','Wymiana ekranu dotykowego (digitizer)','','description: Wymiana warstwy dotykowej (digitizer) lub całego panelu w laptopach dotykowych i 2-w-1. symptoms: • Dotyk nie działa / reaguje błędnie • Pęknięta szyba dotykowa • Duchy dotyku (phantom touch) diagnosis: • Ustal, czy panel jest klejony (digitizer + LCD razem). • Sprawdź sterownik HID/dotyku w systemie. • Test kalibracji dotyku. repair: • Podgrzej i rozklej ramkę (stacja grzewcza / separator). • Wymień digitizer lub cały moduł (LCD+dotyk). • Podłącz taśmy dotyku i obrazu, przetestuj przed sklejeniem. • Sklej z użyciem kleju OCA/B-7000. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-063','topic','','Naprawa / serwis pamięci RAM','','description: Reanimacja RAM: czyszczenie styków, przekładanie modułów, testy błędów — częsta przyczyna braku obrazu i restartów. symptoms: • Brak obrazu / brak POST • Niebieskie ekrany (BSOD), losowe restarty • Sygnał dźwiękowy (beep) po starcie diagnosis: • Wyjmij i włóż ponownie moduły (reseating). • Testuj po jednym module w różnych slotach. • MemTest86 na błędy pamięci. repair: • Wyczyść złote styki gumką/IPA (bez rys). • Przełóż moduły zgodnie z instrukcją płyty (dual channel). • Wymień uszkodzony moduł. • Ustaw XMP/EXPO w BIOS. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-064','topic','','Serwis karty graficznej (PC/laptop)','','description: Pełny serwis GPU: wymiana wentylatorów, pastu i padów termicznych, reflow/reball przy artefaktach. symptoms: • Artefakty, brak obrazu, przegrzewanie GPU • Głośne/nie kręcące się wentylatory • Wysoka temperatura VRAM/hotspot diagnosis: • Test w innym PC / na HDMI. • Zmierz temperatury (hotspot/VRAM). • Sprawdź wentylatory i stan padów. repair: • Rozłóż karte, wymień pastę i pady termiczne. • Wymień wentylatory na nowe. • Reflow/reball układu GPU (stacja BGA — serwis). • Wyczyść radiator z kurzu. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-065','topic','','Naprawa gniazda LAN / RJ45','','description: Naprawa portu sieciowego RJ45 (brak sieci przewodowej, wyłamane gniazdo, brak diod). symptoms: • Brak połączenia przewodowego (kabel OK) • Wyłamane/luźne gniazdo RJ45 • Diody LAN nie świecą diagnosis: • Test innym kablem i portem/switch''em. • Sprawdź kartę sieciową w Menedżerze urządzeń. • Obejrzyj piny gniazda pod kątem uszkodzeń. repair: • Przelutuj / wymień gniazdo RJ45. • Sprawdź magnetyki i kontroler LAN. • Ewentualnie dodaj kartę sieciową USB/PCIe. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-066','topic','','PC: montaż procesora (socket)','','description: Poprawny montaż CPU w komputerze stacjonarnym (AM4/AM5/LGA) bez gięcia pinów. symptoms: • Budowa nowego PC • Wymiana/upgrade procesora • Brak POST po montażu CPU diagnosis: • Dobierz CPU zgodny z socketem i chipsetem płyty. • Sprawdź aktualizację BIOS pod nowszy procesor. repair: • Otwórz dźwignię socketu, ułóż CPU po znaczniku (trójkąt). • Nie dotykaj pinów/padów, dociśnij dźwignią. • Nałóż pastę, zamontuj chłodzenie. • Pierwszy start — wejdź do BIOS, sprawdź detekcję. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-067','topic','','PC: montaż chłodzenia CPU','','description: Montaż chłodzenia powietrznego lub AIO (wodne) na procesorze w PC + pasta termoprzewodząca. symptoms: • Wysokie temperatury CPU • Nowa budowa / wymiana chłodzenia • Głośna praca, throttling diagnosis: • Dobierz chłodzenie do socketu i TDP CPU. • Sprawdź wysokość coolera vs obudowa. repair: • Zamontuj backplate i mocowanie pod socket. • Nałóż pastę (ziarno ryżu). • Dokręć równomiernie na krzyż, podłącz CPU_FAN/PUMP. • AIO: radiator wężykami do dołu/przód, sprawdź temperatury. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-068','topic','','PC: montaż karty graficznej (PCIe)','','description: Poprawne osadzenie karty graficznej w slocie PCIe x16 i przykręcenie do obudowy. symptoms: • Nowa/wymieniana karta graficzna • Brak obrazu z GPU • Karta nie trzyma się w slocie diagnosis: • Użyj górnego slotu PCIe x16. • Sprawdź, czy zasilacz ma odpowiednie złącza i moc. repair: • Zwolnij zatrzask slotu, wciśnij kartę do kliknięcia. • Przykręć śledź do obudowy. • Podłącz zasilanie PCIe (patrz osobna lekcja). • Zainstaluj sterowniki (czysta instalacja DDU). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-069','topic','','PC: zasilanie GPU (8-pin / 12VHPWR)','','description: Prawidłowe podłączenie zasilania karty graficznej — klucz do stabilności i bezpieczeństwa (12VHPWR!). symptoms: • Karta nie startuje / miga dioda zasilania • Restarty pod obciążeniem • Grzejące się złącze diagnosis: • Sprawdź wymagane złącza karty (6/8-pin lub 12VHPWR). • Zweryfikuj moc i amperaż zasilacza. repair: • Użyj oddzielnych kabli PCIe (nie daisy-chain przy mocnych GPU). • 12VHPWR: wepnij DO KOŃCA (klik) — inaczej grozi przepaleniem. • Prowadź kabel bez ostrych zgięć przy wtyczce. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-070','topic','','PC: panel przedni (F_PANEL, USB, audio)','','description: Podłączenie przycisków, diod, USB i audio z frontu obudowy do płyty głównej (najczęstszy problem przy budowie). symptoms: • PC nie reaguje na przycisk power • Diody/porty USB z frontu nie działają • Brak audio z frontu diagnosis: • Znajdź nagłówek F_PANEL w instrukcji płyty. • Zidentyfikuj: PWR_SW, RESET, PWR_LED, HDD_LED. repair: • Podłącz PWR_SW/RESET (polaryzacja bez znaczenia), LED-y zgodnie z +/-. • Wepnij USB 2.0/3.0/USB-C i HD_AUDIO. • Zła dioda? Odwróć wtyczkę LED. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-071','topic','','PC: montaż zasilacza (ATX)','','description: Montaż i podłączenie zasilacza ATX: płyta (24-pin), CPU (EPS 8-pin), GPU, dyski. symptoms: • Nowa budowa / wymiana zasilacza • PC nie startuje (brak zasilania płyty/CPU) • Losowe wyłączenia diagnosis: • Dobierz moc zasilacza do podzespołów (+zapas). • Sprawdź certyfikat 80 PLUS i złącza. repair: • Przykręć zasilacz (wentylator w dół, jeśli jest wlot). • Podłącz 24-pin ATX i 8-pin EPS (CPU). • Podłącz PCIe (GPU), SATA (dyski). • Ustaw przełącznik I/O, pierwszy start. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-072','topic','','PC: montaż dysku (SATA / M.2 NVMe)','','description: Instalacja dysku SSD/HDD SATA oraz M.2 NVMe w komputerze stacjonarnym. symptoms: • Rozbudowa o nowy dysk • Dysk niewykrywany w BIOS • Upgrade na szybki NVMe diagnosis: • Sprawdź wolne sloty M.2 i porty SATA. • Uwaga: niektóre M.2 dzielą pasmo z SATA. repair: • M.2: włóż pod kątem, dokręć śrubką, załóż radiator. • SATA: przykręć dysk, podłącz kabel danych + zasilanie. • W BIOS włącz/sprawdź detekcję, ustaw boot. • Zainicjuj i sformatuj w Windows. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-073','topic','','PC: zarządzanie kablami (airflow)','','description: Estetyczne i praktyczne prowadzenie kabli — lepszy przepływ powietrza i niższe temperatury. symptoms: • Bałagan kabli blokuje airflow • Wysokie temperatury w obudowie • Trudny dostęp do podzespołów diagnosis: • Zaplanuj trasy za tacką płyty. • Policz punkty mocowania / opaski. repair: • Prowadź kable za tacką, wyprowadzaj przy złączach. • Spinaj opaskami/rzepami. • Ustaw wentylatory: wlot z przodu/dołu, wylot z tyłu/góry. • Sprawdź temperatury po uporządkowaniu. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-074','topic','','PC: diagnoza — komputer nie startuje','','description: Systematyczna diagnoza martwego PC: zasilanie, POST, kody beep i diody debug (Q-LED). symptoms: • Brak reakcji na przycisk power • Wiatraki kręcą, brak obrazu • Sygnały dźwiękowe / świecące Q-LED diagnosis: • Sprawdź zasilacz (zworka/tester), 24-pin i 8-pin EPS. • Odczytaj kody beep / diody Q-LED (CPU/DRAM/VGA/BOOT). • Start na minimum: 1 RAM, bez GPU (iGPU) / bez dysków. • Zresetuj BIOS (Clear CMOS). repair: • Popraw/wymień zasilanie lub kable EPS. • Przełóż/wymień RAM (dioda DRAM). • Osadź ponownie GPU / spróbuj iGPU (dioda VGA). • Zaktualizuj BIOS (BIOS Flashback) pod nowe CPU. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-075','topic','','Sekwencja włączania płyty (power sequence)','','description: Jak płyta startuje: od stanu S5, przez sygnały EN, po POST. Klucz do diagnozy „martwych” płyt. symptoms: • Brak reakcji na przycisk zasilania • Reaguje (wiatrak/LED), brak POST • Startuje i wyłącza się/resetuje diagnosis: • Zmierz napięcie na gnieździe zasilacza i baterii. • Pomiar napięć przetwornic w S5 (ALW) i po włączeniu (3/5V, VCORE). • Prześledź sygnały: PWR_SW# → KBC → EN przetwornic → PWRGD. • Obserwuj pobór prądu na zasilaczu serwisowym. repair: • Wymień elementy w obwodzie zasilania (MOSFET/PWM). • Przeprogramuj/wymień BIOS/EC. • Napraw obwody sygnałów EN/PWRGD. • Reball/wymiana PCH/mostu przy braku POST. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-076','topic','','Szyny napięć: ALW/3-5V, VCORE, VRM','','description: Pomiar i zrozumienie głównych napięć płyty: dyżurne (ALW), 3/5V, VCORE oraz kontrolery PWM/VRM. symptoms: • Włącza się, brak obrazu • Losowe wyłączenia pod obciążeniem • Niestabilna praca, błędy krytyczne diagnosis: • Zmierz napięcia na cewkach (VCORE, VGPU, 3/5V, 1.05V, 1.8V). • Sprawdź sygnały EN załączające przetwornice. • Pomiar rezystancji wyjść przetwornic do masy (zwarcia). • Zweryfikuj sterowniki PWM/VRM. repair: • Wymień przetwornice/kontrolery PWM. • Wymień MOSFETy w kluczach. • Wymień zwarte kondensatory przy cewkach. • Sprawdź PWRGD i wartości względem schematu. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-077','topic','','Szukanie zwarć (próba zwarciowa)','','description: Lokalizacja zwartego elementu: pomiar rezystancji do masy + próba zwarciowa z ograniczeniem prądu i termowizją. symptoms: • Nie włącza się, pobiera stały wysoki prąd • Zasilacz serwisowy w limicie prądu • Element grzeje się zaraz po podaniu zasilania diagnosis: • Pomiar rezystancji głównej gałęzi do masy (dziesiątki–setki kΩ = OK). • Podaj prąd z ograniczeniem (1–2A) i szukaj grzejącego elementu. • Użyj termowizji / alkoholu izopropylowego (odparuje na gorącym). repair: • Wylutuj i wymień zwarty element (kondensator/MOSFET/dioda/IC). • Po wymianie ponów pomiar rezystancji — zwarcie musi zniknąć. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-078','topic','','Kontroler EC/KBC','','description: Serce włączania i I/O płyty: zasilanie KBC, sygnał PWR_SW#, kwarc, programowanie firmware EC. symptoms: • Brak reakcji na przycisk power • Nie działa klawiatura/touchpad/włącznik • Brak inicjacji POST diagnosis: • Sprawdź zasilanie KBC (3VALW/3VLP/AVCC). • Kontrola sygnału PWR_SW# do KBC. • Sprawdź rezonator kwarcowy przy KBC. • Pomiar linii LPC/eSPI. repair: • Przeprogramuj/wymień KBC (firmware EC). • Napraw obwód zasilania KBC. • Wymień wadliwy kwarc. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-079','topic','','Zegar RTC i rezonatory (kwarce)','','description: Zegar czasu rzeczywistego i kwarce (32.768 kHz, główny) — bez nich płyta nie wystartuje poprawnie. symptoms: • Nie startuje/zawiesza na wczesnym POST • Zła data/czas mimo ustawienia • Nie da się zresetować BIOS diagnosis: • Zmierz napięcie na bateryjce RTC (~3V). • Sprawdź rezonację na kwarcu (oscyloskop). • Pomiar linii zegara i zasilania PCH/mostu. repair: • Wymień bateryjkę RTC. • Wymień kwarc RTC/główny lub elementy obwodu. • Reball/wymiana PCH przy uszkodzeniu układu. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-080','topic','','Programowanie BIOS/ME (programator SPI)','','description: Odczyt i wgranie wsadu BIOS/ME programatorem SPI (CH341A) z zachowaniem klucza Windows i danych serwisowych. symptoms: • Martwa płyta / brak POST na kodzie • Problemy z wykrywaniem RAM/dysku • Błędy odczytu BIOS diagnosis: • Sprawdź zasilanie kości BIOS/ME. • Kontrola linii SPI/LPC. • Odczytaj zawartość programatorem i porównaj. repair: • Zaprogramuj/wymień kość BIOS/ME (CH341A + klips SOIC8). • Zachowaj oryginalny wsad (klucz, serwis). • Wgraj czysty wsad dla modelu, wstaw dane z oryginału. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-081','topic','','Układ ładowania baterii (charger)','','description: Sekcja ładowania (np. BQ24xxx) i MOSFETy — dlaczego laptop nie ładuje lub nie startuje na baterii. symptoms: • Nie ładuje (działa tylko z zasilacza) • Nie startuje na baterii / bateria niewykryta • Grzejący się układ chargera diagnosis: • Sprawdź układ chargera: zasilanie, sygnały EN, napięcie wyjściowe. • Pomiar bramek MOSFETów ładowania. • Sprawdź linie komunikacji z baterią (SMBus). repair: • Wymień układ chargera i MOSFETy. • Wymień kondensatory filtrujące. • Napraw linie komunikacji z baterią. source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-082','topic','','Czytanie schematów i Boardview','','description: Jak czytać schematy elektroniczne i mapy płyty (Boardview) — fundament każdej naprawy na poziomie płyty (laptop, GPU, PC). symptoms: • Nie wiesz, gdzie zmierzyć napięcie • Trudno znaleźć element na płycie • Nie rozumiesz działania fragmentu układu diagnosis: • Naucz się oznaczeń: cewki (PL/L), kondensatory (PC/C), MOSFETy (PQ/Q), IC (PU/U). • Dopasuj schemat i Boardview do MODELU płyty/karty (numer z płyty). • W Boardview klikaj element → podświetla wszystkie punkty tej sieci (net). repair: • Śledź sieć (net) od punktu pomiaru do źródła. • Porównaj napięcia/rezystancje ze schematem i sprawną płytą. • Używaj schematu do doboru zamienników (part number). source: Kurs naprawy PC i laptopów – 707 stron','','','Kurs naprawy PC i laptopów – 707 stron'),
('topic:KURS-083','topic','','Pomiary na płycie (multimetr)','','description: Podstawy pomiarów: tryb diody, rezystancja do masy, napięcia stałe — bez tego nie zdiagnozujesz płyty. symptoms: • Nie wiesz, czy element jest sprawny • Podejrzenie zwarcia / przerwy • Weryfikacja napięć zasilających diagnosis: • Tryb diody: sprawdzaj kondensatory/MOSFETy względem masy (spadek napięcia). • Rezystancja do masy: bardzo mała = zwarcie. • Pomiar DC: porównaj z wartościami ze schematu. repair: • Zlokalizuj element odbiegający od normy i wymień. • Potwierdź naprawę ponownym pomiarem. • Dokumentuj wartości względem sprawnej płyty. Materiały dodatkowe serwisu naprawa Kompletny Podręcznik Naprawy Laptopów i Komputerów (Wersja Rozszerzona) Ten podręcznik zawiera rozbudowane informacje dotyczące diagnostyki, konserwacji i naprawy laptopów oraz komputerów stacjonarnych. Ten podręcznik zawiera rozbudowane informacje dotyczące diagnostyki, konserwacji i naprawy laptopów oraz komputerów stacjonarnych. Ten podręcznik zawiera rozbudowane informacje dotyczące diagnostyki, konserwacji i naprawy laptopów oraz komputerów stacjonarnych. Ten podręcznik zawiera rozbudowane informacje dotyczące diagnostyki, konserwacji i naprawy laptopów oraz komputerów stacjonarnych. Ten podręcznik zawiera rozbudowane informacje dotyczące diagnostyki, konserwacji i naprawy laptopów oraz komputerów stacjonarnych. Budowa komputera Sekcja 1 Podczas naprawy należy rozpocząć od oględzin, pomiarów napięć oraz testów podstawowych podzespołów. Najczęstsze problemy dotyczą zasilania, pamięci RAM, dysków danych, chłodzenia i uszkodzeń mechanicznych. Diagnostyka powinna przebiegać według schematu: zasilacz, płyta główna, procesor, pamięć RAM, dysk, karta graficzna oraz urządzenia peryferyjne. W każdym przypadku należy dokumentować wykonane czynności, zachowywać zasady bezpieczeństwa i stosować odpowiednie narzędzia serwisowe. Podczas naprawy należy rozpocząć od oględzin, pomiarów napięć oraz testów podstawowych podzespołów.